from datetime import datetime, timezone
from .extensions import db

def now(): return datetime.now(timezone.utc)
class User(db.Model):
    id=db.Column(db.Integer,primary_key=True); google_sub=db.Column(db.String(255),unique=True); email=db.Column(db.String(255),unique=True,nullable=False,index=True); name=db.Column(db.String(120),nullable=False); profile_image_url=db.Column(db.String(500)); role=db.Column(db.String(20),default='student',nullable=False); branch=db.Column(db.String(80)); academic_year=db.Column(db.String(30)); is_active=db.Column(db.Boolean,default=True); created_at=db.Column(db.DateTime(timezone=True),default=now); last_login_at=db.Column(db.DateTime(timezone=True),default=now)
class Event(db.Model):
    id=db.Column(db.Integer,primary_key=True); title=db.Column(db.String(180),nullable=False); slug=db.Column(db.String(220),unique=True,nullable=False); description=db.Column(db.Text,nullable=False); category=db.Column(db.String(60),nullable=False); banner_url=db.Column(db.String(500)); venue=db.Column(db.String(180),nullable=False); starts_at=db.Column(db.DateTime,nullable=False,index=True); ends_at=db.Column(db.DateTime,nullable=False); registration_deadline=db.Column(db.DateTime); capacity=db.Column(db.Integer); organizer_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False); status=db.Column(db.String(30),default='published'); created_at=db.Column(db.DateTime,default=datetime.utcnow); organizer=db.relationship('User',backref='events')
class Registration(db.Model):
    id=db.Column(db.Integer,primary_key=True); user_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False); event_id=db.Column(db.Integer,db.ForeignKey('event.id'),nullable=False); status=db.Column(db.String(20),default='active'); registered_at=db.Column(db.DateTime,default=datetime.utcnow); cancelled_at=db.Column(db.DateTime); user=db.relationship('User',backref='registrations'); event=db.relationship('Event',backref='registrations'); __table_args__=(db.UniqueConstraint('user_id','event_id',name='uq_registration'),)
class Club(db.Model):
    id=db.Column(db.Integer,primary_key=True); name=db.Column(db.String(140),nullable=False); slug=db.Column(db.String(160),unique=True,nullable=False); description=db.Column(db.Text,nullable=False); category=db.Column(db.String(60),nullable=False); logo_url=db.Column(db.String(500)); contact_email=db.Column(db.String(255)); website_url=db.Column(db.String(500)); recruitment_status=db.Column(db.String(30),default='closed'); publication_status=db.Column(db.String(30),default='published'); manager_id=db.Column(db.Integer,db.ForeignKey('user.id'))
class Notice(db.Model):
    id=db.Column(db.Integer,primary_key=True); title=db.Column(db.String(180),nullable=False); content=db.Column(db.Text,nullable=False); category=db.Column(db.String(60),nullable=False); issuer=db.Column(db.String(140),nullable=False); deadline=db.Column(db.DateTime); source_url=db.Column(db.String(500)); publication_status=db.Column(db.String(30),default='published'); author_id=db.Column(db.Integer,db.ForeignKey('user.id')); created_at=db.Column(db.DateTime,default=datetime.utcnow); author=db.relationship('User')
class Favorite(db.Model):
    id=db.Column(db.Integer,primary_key=True); user_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False); event_id=db.Column(db.Integer,db.ForeignKey('event.id'),nullable=False); __table_args__=(db.UniqueConstraint('user_id','event_id',name='uq_favorite'),)
class StickyNote(db.Model):
    id=db.Column(db.Integer,primary_key=True); user_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False); title=db.Column(db.String(140),nullable=False); content=db.Column(db.Text,nullable=False); is_pinned=db.Column(db.Boolean,default=False); updated_at=db.Column(db.DateTime,default=datetime.utcnow,onupdate=datetime.utcnow); user=db.relationship('User',backref='notes')
class Notification(db.Model):
    id=db.Column(db.Integer,primary_key=True); user_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False); title=db.Column(db.String(180),nullable=False); message=db.Column(db.Text,nullable=False); read_at=db.Column(db.DateTime); created_at=db.Column(db.DateTime,default=datetime.utcnow); user=db.relationship('User',backref='notifications')
class CampusLocation(db.Model):
    id=db.Column(db.Integer,primary_key=True); name=db.Column(db.String(140),nullable=False); description=db.Column(db.Text,nullable=False); latitude=db.Column(db.Float,nullable=False); longitude=db.Column(db.Float,nullable=False); category=db.Column(db.String(60),nullable=False); publication_status=db.Column(db.String(30),default='published')
